head.b:skin:
/* Fieldnote 1.0.0 — original design by Gonk Themes (designed by Claude). GPL-2.0-or-later. */
:root{color-scheme:light;--fn-paper:#f3eee2;--fn-card:#fbf8f0;--fn-sunk:#e9e2d1;--fn-ink:#23261f;--fn-muted:#5b604f;--fn-line:#d5ccb6;--fn-rule:#e4dccb;--fn-moss:#3d5a36;--fn-rust:#a9512c;--fn-on:#fbf8f0;--fn-max:1180px;--fn-serif:"Iowan Old Style","Palatino Linotype",Palatino,"Book Antiqua",Georgia,serif;--fn-sans:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;--fn-mono:ui-monospace,SFMono-Regular,Consolas,monospace}
html[data-fieldnote-mode=dusk]{color-scheme:dark;--fn-paper:#1b1e19;--fn-card:#23271f;--fn-sunk:#2b3026;--fn-ink:#ece6d6;--fn-muted:#b3ad9b;--fn-line:#41473a;--fn-rule:#30352b;--fn-moss:#9cc08f;--fn-rust:#e39a72;--fn-on:#1b1e19}
html[data-fieldnote-mode=dusk] .fn-plate img,html[data-fieldnote-mode=dusk] .fn-card-art img[src$='.svg'],html[data-fieldnote-mode=dusk] .fn-card-art img[src^='data:image/svg'],html[data-fieldnote-mode=dusk] .fn-figure img[src$='.svg']{filter:invert(.88) hue-rotate(180deg)}
*,*:before,*:after{box-sizing:border-box}html{scroll-padding-top:90px}body{margin:0;background:var(--fn-paper);color:var(--fn-ink);font:17px/1.7 var(--fn-serif);-webkit-font-smoothing:antialiased}
a{color:inherit;text-underline-offset:4px;text-decoration-thickness:1px}a:hover{color:var(--fn-rust)}img,svg,video{max-width:100%}img{height:auto}button,input,select,textarea{font:inherit}button{cursor:pointer}
:focus-visible{outline:3px solid var(--fn-rust);outline-offset:4px}
.fn-wrap{width:min(var(--fn-max),calc(100% - 64px));margin-inline:auto}
.fn-skip{position:absolute;left:16px;top:-100px;z-index:20;background:var(--fn-ink);color:var(--fn-paper);padding:12px 16px}.fn-skip:focus{top:12px}
.fn-sr{position:absolute!important;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.fn-demo-note{font:11px/1.6 var(--fn-mono);letter-spacing:.6px;text-align:center;padding:7px 16px;background:var(--fn-moss);color:var(--fn-on)}
/* Header: a notebook cover band */
.fn-header{border-bottom:1px solid var(--fn-line)}.fn-header-inner{display:flex;align-items:center;gap:28px;min-height:88px}
.fn-brand{display:flex;align-items:center;gap:13px;text-decoration:none;color:var(--fn-ink)}.fn-brand:hover{color:var(--fn-ink)}
.fn-mark{width:42px;height:42px;border:1.5px solid var(--fn-moss);border-radius:50%;display:grid;place-items:center;color:var(--fn-moss);flex-shrink:0}.fn-mark svg{width:24px;height:24px}
.fn-brand-text{display:flex;flex-direction:column;line-height:1.1}.fn-brand-text b{font-size:26px;font-weight:600;letter-spacing:-.4px}.fn-brand-text small{font:10px/1.6 var(--fn-mono);letter-spacing:1.2px;text-transform:uppercase;color:var(--fn-muted);margin-top:4px}
.fn-nav{display:flex;gap:26px;margin-left:auto;font:14px var(--fn-sans)}.fn-nav a,.fn-wp .fn-header .wp-block-navigation-item__content{text-decoration:none;min-height:44px;display:inline-flex;align-items:center}
.fn-tools{display:flex;gap:8px;align-items:center}
.fn-icon{width:44px;height:44px;border:1px solid var(--fn-line);border-radius:50%;background:transparent;color:var(--fn-ink);display:grid;place-items:center}.fn-icon svg{width:19px;height:19px}.fn-icon:hover{border-color:var(--fn-moss)}
.fn-mobile{display:none;position:relative}.fn-mobile summary{list-style:none;min-height:44px;display:inline-flex;align-items:center;padding:0 16px;border:1px solid var(--fn-line);border-radius:999px;font:13px var(--fn-sans)}.fn-mobile summary::-webkit-details-marker{display:none}
.fn-mobile nav{position:absolute;right:0;top:52px;z-index:10;background:var(--fn-card);border:1px solid var(--fn-line);border-radius:10px;padding:8px;min-width:210px;display:grid;box-shadow:0 14px 40px rgba(0,0,0,.12)}.fn-mobile nav a{padding:10px 12px;min-height:44px;display:flex;align-items:center;text-decoration:none;font:15px var(--fn-sans)}
/* Season strip + field-guide chips */
.fn-season{display:flex;flex-wrap:wrap;align-items:center;gap:10px 22px;padding-block:18px;border-bottom:1px solid var(--fn-line);font:12px/1.5 var(--fn-mono);letter-spacing:1px;text-transform:uppercase;color:var(--fn-muted)}
.fn-season .fn-now{color:var(--fn-moss);font-weight:700}.fn-season .fn-sep{flex:1;border-top:1px dashed var(--fn-line);min-width:30px}
.fn-guide{display:flex;flex-wrap:wrap;gap:9px;padding-block:18px;border-bottom:1px solid var(--fn-line)}.fn-guide>span{font:11px/44px var(--fn-mono);letter-spacing:1px;color:var(--fn-muted);margin-right:8px}
.fn-chip{display:inline-flex;align-items:center;min-height:44px;padding:0 15px;border:1px solid var(--fn-line);border-radius:4px;font:14px var(--fn-sans);text-decoration:none;background:var(--fn-card)}.fn-chip:hover{border-color:var(--fn-moss);color:var(--fn-moss)}
/* Today's observation: the lead entry */
.fn-lead-entry{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:48px;align-items:center;padding-block:56px;border-bottom:1px solid var(--fn-line)}
.fn-kicker{font:12px/1.5 var(--fn-mono);letter-spacing:1.4px;text-transform:uppercase;color:var(--fn-rust);display:flex;gap:10px;align-items:center}.fn-kicker:before{content:"";width:22px;border-top:1.5px solid currentColor}
.fn-lead-entry h1{font-size:clamp(40px,5vw,66px);line-height:1.06;letter-spacing:-1.6px;font-weight:600;margin:18px 0 20px}.fn-lead-entry h1 em{color:var(--fn-moss)}
.fn-intro{font-size:20px;line-height:1.6;color:var(--fn-muted);max-width:560px;margin:0 0 28px}
.fn-plate{position:relative;background:var(--fn-card);border:1px solid var(--fn-line);padding:28px 28px 22px;box-shadow:6px 6px 0 var(--fn-sunk)}.fn-plate img{display:block;width:100%;aspect-ratio:4/3;object-fit:contain}
.fn-plate figcaption{display:flex;justify-content:space-between;gap:16px;border-top:1px solid var(--fn-line);margin-top:16px;padding-top:12px;font:11px/1.6 var(--fn-mono);letter-spacing:.8px;text-transform:uppercase;color:var(--fn-muted)}
.fn-tape{position:absolute;top:-11px;left:50%;width:96px;height:22px;margin-left:-48px;background:color-mix(in srgb,var(--fn-rust) 25%,transparent);transform:rotate(-3deg)}
.fn-button{display:inline-flex;align-items:center;gap:8px;min-height:46px;padding:0 20px;border-radius:4px;background:var(--fn-moss);color:var(--fn-on);font:600 14px var(--fn-sans);text-decoration:none;border:1px solid var(--fn-moss)}.fn-button:hover{color:var(--fn-on);filter:brightness(1.1)}.fn-button.ghost{background:transparent;color:var(--fn-moss)}
.fn-text-link{font:14px var(--fn-sans);color:var(--fn-moss);min-height:44px;display:inline-flex;align-items:center}
.fn-actions{display:flex;gap:18px;align-items:center;flex-wrap:wrap}
/* Content grid + specimen cards */
.fn-content-grid{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:48px;padding-block:44px 64px}
.fn-section-heading{display:flex;justify-content:space-between;align-items:baseline;gap:20px;border-bottom:2px solid var(--fn-ink);padding-bottom:10px;margin-bottom:28px}.fn-section-heading h2{margin:0;font-size:28px;font-weight:600;letter-spacing:-.5px}.fn-section-heading p{margin:0;font:11px var(--fn-mono);letter-spacing:1.2px;color:var(--fn-muted)}
.fn-cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:28px}
.fn-card{position:relative;background:var(--fn-card) repeating-linear-gradient(to bottom,transparent 0 31px,var(--fn-rule) 31px 32px);border:1px solid var(--fn-line);padding:22px 22px 18px;display:flex;flex-direction:column}
.fn-card-art{display:block;background:var(--fn-paper);border:1px solid var(--fn-line);margin-bottom:16px}.fn-card-art img{display:block;width:100%;aspect-ratio:16/10;object-fit:contain;padding:10px}
.fn-tag{font:11px/1.5 var(--fn-mono);letter-spacing:1px;text-transform:uppercase;color:var(--fn-rust);text-decoration:none}
.fn-card h3{font-size:23px;line-height:1.28;letter-spacing:-.3px;font-weight:600;margin:8px 0 8px}.fn-card h3 a{text-decoration:none}.fn-card p{margin:0 0 14px;color:var(--fn-muted);font-size:16px;line-height:1.6}
.fn-observed{margin-top:auto;display:flex;flex-wrap:wrap;gap:6px 14px;border-top:1px dashed var(--fn-line);padding-top:10px;font:11px/1.6 var(--fn-mono);letter-spacing:.6px;color:var(--fn-muted)}
.fn-observed span:before{content:"◦ ";color:var(--fn-moss)}
.fn-pagination{display:flex;justify-content:space-between;gap:16px;margin-top:34px;font:14px var(--fn-sans)}.fn-pagination a{min-height:44px;display:inline-flex;align-items:center;color:var(--fn-moss)}
.fn-empty{padding:36px;border:1px dashed var(--fn-line);text-align:center}
/* Field kit sidebar */
.fn-kit{border-left:1px solid var(--fn-line);padding-left:30px;display:grid;gap:34px;align-content:start}
.fn-kit h2{font-size:19px;font-weight:600;margin:0 0 14px;display:flex;align-items:center;gap:8px}.fn-kit h2:before{content:"";width:9px;height:9px;border:1.5px solid var(--fn-moss);border-radius:50%}
.fn-search{display:flex;gap:6px}.fn-search input{flex:1;min-width:0;min-height:44px;border:1px solid var(--fn-line);background:var(--fn-card);color:var(--fn-ink);padding:0 12px;border-radius:4px;font:14px var(--fn-sans)}.fn-search button{min-width:44px;min-height:44px;border:1px solid var(--fn-moss);background:var(--fn-moss);color:var(--fn-on);border-radius:4px}
.fn-notebook{background:var(--fn-sunk);padding:20px;border-radius:2px;font-size:15px}.fn-notebook p{margin:0 0 10px}
.fn-list{list-style:none;margin:0;padding:0;counter-reset:fn}.fn-list li{counter-increment:fn;display:grid;grid-template-columns:28px 1fr;padding:10px 0;border-bottom:1px solid var(--fn-line);font-size:15px;line-height:1.45}.fn-list li:before{content:counter(fn,decimal-leading-zero);font:11px/2 var(--fn-mono);color:var(--fn-rust)}.fn-list a{text-decoration:none}.fn-list small{display:block;font:11px var(--fn-mono);color:var(--fn-muted);margin-top:3px}
.fn-kit-links{display:flex;flex-wrap:wrap;gap:8px}
/* Article: reading column + margin notes */
.fn-article{max-width:740px;margin:0 auto;padding:46px 0 70px}
.fn-breadcrumb{font:12px var(--fn-mono);color:var(--fn-muted);display:flex;gap:10px;flex-wrap:wrap;margin-bottom:20px}.fn-breadcrumb a{text-decoration:none;min-height:24px}
.fn-article h1{font-size:clamp(36px,4.4vw,56px);line-height:1.1;letter-spacing:-1.2px;font-weight:600;margin:14px 0 18px}
.fn-standfirst{font-size:21px;line-height:1.6;color:var(--fn-muted);margin:0 0 22px}
.fn-entry-meta{display:flex;flex-wrap:wrap;gap:8px 18px;padding-block:12px;border-block:1px solid var(--fn-line);font:12px/1.6 var(--fn-mono);color:var(--fn-muted);margin-bottom:30px}
.fn-figure{margin:0 0 34px;background:var(--fn-card);border:1px solid var(--fn-line);padding:22px}.fn-figure img{display:block;width:100%;aspect-ratio:16/9;object-fit:contain}.fn-figure figcaption{font:12px var(--fn-mono);color:var(--fn-muted);margin-top:12px}
.fn-prose{font-size:19px;line-height:1.8}.fn-prose h2{font-size:30px;line-height:1.25;letter-spacing:-.5px;margin:46px 0 14px;font-weight:600}.fn-prose h3{font-size:23px;margin:34px 0 10px}
.fn-prose blockquote{margin:30px 0;padding:6px 0 6px 24px;border-left:3px solid var(--fn-moss);font-size:23px;font-style:italic;line-height:1.5}
.fn-prose ul,.fn-prose ol{padding-left:26px}.fn-prose li{margin:6px 0}
.fn-prose table{width:100%;border-collapse:collapse;font:15px var(--fn-sans);margin:26px 0}.fn-prose th,.fn-prose td{text-align:left;padding:10px 12px;border-bottom:1px solid var(--fn-line)}.fn-prose th{font:11px var(--fn-mono);letter-spacing:1px;text-transform:uppercase;color:var(--fn-muted)}
.fn-prose code,.fn-prose pre{font:14px/1.6 var(--fn-mono)}.fn-prose pre{background:var(--fn-sunk);padding:16px;overflow:auto}
.fn-margin{position:relative;margin:24px 0;padding:14px 16px;background:var(--fn-sunk);border-left:3px solid var(--fn-rust);font:15px/1.55 var(--fn-sans)}.fn-margin b{display:block;font:11px var(--fn-mono);letter-spacing:1px;text-transform:uppercase;color:var(--fn-rust);margin-bottom:4px}
@media(min-width:1200px){.fn-prose .fn-margin{float:right;clear:right;width:230px;margin:4px -280px 18px 0;background:transparent;border-left:0;border-top:2px solid var(--fn-rust);padding:10px 0 0}}
.fn-author{display:flex;gap:16px;align-items:flex-start;margin-top:44px;padding-top:22px;border-top:2px solid var(--fn-ink)}.fn-author p{margin:4px 0 0;color:var(--fn-muted);font-size:15px}
.fn-initials{width:46px;height:46px;border-radius:50%;background:var(--fn-moss);color:var(--fn-on);display:grid;place-items:center;font:600 15px var(--fn-sans);flex-shrink:0}
.fn-share{display:flex;gap:12px;flex-wrap:wrap;margin-top:24px}.fn-share a,.fn-share button{min-height:44px;display:inline-flex;align-items:center;padding:0 16px;border:1px solid var(--fn-line);background:transparent;color:var(--fn-ink);border-radius:4px;font:14px var(--fn-sans);text-decoration:none}
/* Banner + RSS */
.fn-banner{display:flex;justify-content:space-between;align-items:center;gap:28px;padding:34px 38px;margin-bottom:64px;background:var(--fn-moss);color:var(--fn-on)}.fn-banner h2{margin:6px 0 8px;font-size:28px;font-weight:600;letter-spacing:-.4px}.fn-banner p{margin:0;max-width:620px;opacity:.9;font-size:16px}.fn-banner .fn-kicker{color:var(--fn-on)}.fn-banner .fn-button{background:var(--fn-on);color:var(--fn-moss);border-color:var(--fn-on);flex-shrink:0}
.fn-rss p{font-size:15px;color:var(--fn-muted);margin:0 0 14px}
/* Footer */
.fn-footer{border-top:2px solid var(--fn-ink);padding-block:40px 34px;font:14px var(--fn-sans)}.fn-footer-top{display:flex;justify-content:space-between;gap:40px;flex-wrap:wrap}.fn-footer-top p{max-width:380px;color:var(--fn-muted);font-family:var(--fn-serif);font-size:16px}
.fn-footer-links{display:flex;gap:22px;flex-wrap:wrap;align-content:flex-start}.fn-footer-links a{min-height:44px;display:inline-flex;align-items:center;text-decoration:none}
.fn-footer-bottom{display:flex;justify-content:space-between;flex-wrap:wrap;gap:16px;margin-top:28px;padding-top:18px;border-top:1px solid var(--fn-line);font:12px var(--fn-mono);color:var(--fn-muted)}.fn-credit a{color:var(--fn-moss)}
/* Native Blogger */
.fn-blogger .widget{margin:0}.fn-blogger .post-body{overflow-wrap:anywhere}.fn-blogger .post-body img{max-width:100%;height:auto}.fn-blogger .post-body iframe{max-width:100%}.fn-blogger .Label ul,.fn-blogger .PageList ul,.fn-blogger .BlogArchive ul{list-style:none;padding:0;margin:0;display:flex;flex-wrap:wrap;gap:8px}.fn-blogger .Label a,.fn-blogger .BlogArchive a{display:inline-flex;align-items:center;min-height:44px;padding:0 13px;border:1px solid var(--fn-line);border-radius:4px;background:var(--fn-card);text-decoration:none;font:14px var(--fn-sans)}.fn-blogger .widget h2{font-size:19px;margin:0 0 14px}.fn-blogger .comments{margin-top:44px;font:15px var(--fn-sans)}.fn-blogger .comments textarea,.fn-blogger .comments iframe{width:100%}
/* Native WordPress blocks */
.fn-wp .wp-site-blocks{padding:0}.fn-wp .wp-block-template-part{margin:0}.fn-wp .fn-cards.wp-block-post-template{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:28px;list-style:none;margin:0;padding:0}.fn-wp .fn-cards>li{margin:0;background:var(--fn-card) repeating-linear-gradient(to bottom,transparent 0 31px,var(--fn-rule) 31px 32px);border:1px solid var(--fn-line);padding:22px 22px 18px;display:flex;flex-direction:column}.fn-wp .fn-cards .wp-block-post-featured-image{margin:0 0 16px;border:1px solid var(--fn-line);background:var(--fn-paper)}.fn-wp .fn-cards .wp-block-post-featured-image img{aspect-ratio:16/10;object-fit:cover}.fn-wp .fn-cards .wp-block-post-terms{font:11px/1.5 var(--fn-mono);letter-spacing:1px;text-transform:uppercase}.fn-wp .fn-cards .wp-block-post-terms a{color:var(--fn-rust);text-decoration:none}.fn-wp .fn-cards .wp-block-post-title{font-size:23px;line-height:1.28;margin:8px 0}.fn-wp .fn-cards .wp-block-post-title a{text-decoration:none}.fn-wp .fn-cards .wp-block-post-excerpt{color:var(--fn-muted);font-size:16px}.fn-wp .fn-cards .wp-block-post-excerpt__more-text{display:none}.fn-wp .fn-observed{margin-top:auto}.fn-wp .fn-observed>*{margin:0}.fn-wp .wp-block-navigation{font:14px var(--fn-sans)}.fn-wp .wp-block-page-list{gap:26px}.fn-wp .fn-kit .wp-block-search__inside-wrapper{gap:6px}.fn-wp .fn-kit .wp-block-search__input{min-height:44px;border:1px solid var(--fn-line);background:var(--fn-card);color:var(--fn-ink);border-radius:4px}.fn-wp .fn-kit .wp-block-search__button{min-height:44px;background:var(--fn-moss);color:var(--fn-on);border-radius:4px;border:0}.fn-wp .fn-kit .wp-block-latest-posts,.fn-wp .fn-kit .wp-block-categories{list-style:none;padding:0;margin:0}.fn-wp .fn-kit .wp-block-latest-posts li,.fn-wp .fn-kit .wp-block-categories li{padding:9px 0;border-bottom:1px solid var(--fn-line);font-size:15px}.fn-wp .fn-kit .wp-block-latest-posts a,.fn-wp .fn-kit .wp-block-categories a{text-decoration:none}.fn-wp .fn-article .wp-block-post-content{font-size:19px;line-height:1.8}.fn-wp .wp-block-comments{margin-top:44px;font:15px var(--fn-sans)}.fn-wp .wp-block-query-pagination{margin-top:34px;font:14px var(--fn-sans)}
@media(max-width:1000px){.fn-wrap{width:calc(100% - 40px)}.fn-content-grid{grid-template-columns:minmax(0,1fr) 250px;gap:30px}.fn-kit{padding-left:22px}.fn-lead-entry{gap:30px}}
@media(max-width:800px){.fn-nav,.fn-wp .fn-header .wp-block-navigation{display:none}.fn-mobile{display:block}.fn-tools{margin-left:auto}.fn-lead-entry{grid-template-columns:1fr;padding-block:36px}.fn-content-grid{grid-template-columns:1fr}.fn-kit{border-left:0;padding-left:0;border-top:2px solid var(--fn-ink);padding-top:30px}.fn-banner{flex-direction:column;align-items:flex-start;padding:28px}}
@media(max-width:600px){.fn-wrap{width:calc(100% - 32px)}.fn-cards,.fn-wp .fn-cards.wp-block-post-template{grid-template-columns:1fr}.fn-brand-text b{font-size:22px}.fn-header-inner{min-height:76px;gap:12px}.fn-intro{font-size:18px}.fn-prose{font-size:18px}.fn-season .fn-sep{display:none}.fn-plate{padding:18px 18px 14px}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
@media print{.fn-header,.fn-kit,.fn-footer,.fn-season,.fn-guide,.fn-banner,.fn-share,.fn-demo-note,.fn-skip{display:none!important}body{background:#fff;color:#000}.fn-margin{float:none!important;width:auto!important;margin:12px 0!important}a{text-decoration:underline}}

[hidden]{display:none!important}

/* Blogger: keep the public surface Fieldnote-owned on restored blogs. */
.fn-blogger #navbar-iframe,.fn-blogger #navbar,.fn-blogger .navbar{display:none!important}
.fn-blogger .widget:not(.Blog):not(.Label):not(.BlogArchive):not(.HTML):not(.PageList):not(.Profile){display:none!important}
.fn-blogger .fn-kit .widget{margin:0}.fn-blogger .fn-kit .Header,.fn-blogger .fn-kit .BlogSearch{display:none}
.fn-blogger .fn-footer .PageList h2{display:none}.fn-blogger .fn-footer .PageList ul{gap:20px}.fn-blogger .fn-footer .PageList a{border:0;background:none;padding:0}
body#layout .fn-lead-entry,body#layout .fn-season,body#layout .fn-guide,body#layout .fn-banner{display:none}body#layout .fn-content-grid{display:block}body#layout .widget{display:block!important}body#layout .section{min-height:80px;margin:15px}

body.script:
//
/* Fieldnote — no tracking, no external requests. Day/dusk reading mode, mobile menu escape, copy link. */
(()=>{'use strict';
const root=document.documentElement;
try{const saved=localStorage.getItem('gonk-fieldnote-mode');if(['day','dusk'].includes(saved))root.dataset.fieldnoteMode=saved;}catch{}
for(const button of document.querySelectorAll('[data-fieldnote-toggle]')){
 button.hidden=false;
 const update=()=>{const dusk=root.dataset.fieldnoteMode==='dusk';button.setAttribute('aria-pressed',String(dusk));button.setAttribute('aria-label',dusk?'Switch to day reading mode':'Switch to dusk reading mode');};
 update();
 button.addEventListener('click',()=>{root.dataset.fieldnoteMode=root.dataset.fieldnoteMode==='dusk'?'day':'dusk';try{localStorage.setItem('gonk-fieldnote-mode',root.dataset.fieldnoteMode);}catch{}update();});
}
// Season label from the reader's own clock. Add data-fieldnote-hemisphere="south" to <html> to flip it.
const names=['Winter','Winter','Spring','Spring','Spring','Summer','Summer','Summer','Autumn','Autumn','Autumn','Winter'];
const flip={Winter:'Summer',Summer:'Winter',Spring:'Autumn',Autumn:'Spring'};
let season=names[new Date().getMonth()];if(root.dataset.fieldnoteHemisphere==='south')season=flip[season];
for(const el of document.querySelectorAll('[data-fieldnote-season]'))el.textContent=season+' · '+new Date().toLocaleDateString(undefined,{day:'numeric',month:'long'});
const menu=document.querySelector('.fn-mobile');
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu?.open){menu.open=false;menu.querySelector('summary')?.focus();}});
for(const button of document.querySelectorAll('[data-fieldnote-copy]')){
 button.hidden=false;
 button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(location.href);button.textContent='Link copied';}catch{button.textContent='Copy the address from your browser';}});
}
})();

